namespace LunarCal.Core.Chat;

/// <summary>
/// FR-BYOK-7: Vendor-neutral participant role in a chat conversation.
/// </summary>
public enum ChatMessageRole
{
    /// <summary>System instruction defining model persona or behavioral boundaries.</summary>
    System,

    /// <summary>Message originated from the user.</summary>
    User,

    /// <summary>Message generated by the chat model.</summary>
    Model,

    /// <summary>Message containing outputs from local tool execution.</summary>
    Tool
}
